import {loadProvider,isConnected} from './providers.js';
import {competitions,checkedAt,eliteSchedule,eliteTV,eliteMatches,broadcasts,currentTV,gblStandings} from './data.js';
import {escapeHTML as e,normalizeFootball,calculateTable,athensDay,chooseRound,filterMatches,shiftDay} from './core.js';
const $=id=>document.getElementById(id);
const nav=[['football','⚽','Ποδόσφαιρο'],['basketball','◉','Μπάσκετ'],['tv','▣','Τηλεόραση'],['matches','▦','Αγώνες'],['standings','≡','Βαθμολογίες']];
const state={tab:'matches',id:'elite',season:'2026-27',matches:[],round:'',search:'',favorites:read('sh-favorites',[]),only:false,request:0,meta:null,tvDate:athensDay(),archive:false};
if(!Array.isArray(state.favorites))state.favorites=[];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{return false;}}
const allTV={id:'all-tv',name:'Όλες οι διοργανώσεις',sport:'all',url:'https://www.novasports.gr/tv-program/'};
function current(){return state.id==='all-tv'?allTV:competitions.find(c=>c.id===state.id);}
function dateLabel(d){return new Intl.DateTimeFormat('el-GR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Athens'}).format(new Date(d+'T12:00:00+03:00'));}
function timestamp(d){return new Intl.DateTimeFormat('el-GR',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Athens'}).format(new Date(d));}
function link(url,text){return `<a href="${e(url)}" target="_blank" rel="noopener">${e(text)} ↗</a>`;}
function renderNav(){for(const id of ['side-nav','top-nav','bottom-nav']){$(id).innerHTML=nav.map(([key,icon,label])=>`<button type="button" data-tab="${key}" class="${state.tab===key?'active':''}" ${state.tab===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('');}}
function choices(){const allowed=state.tab==='tv'?[allTV,...competitions]:competitions.filter(c=>!['football','basketball'].includes(state.tab)||c.sport===state.tab);if(!allowed.some(c=>c.id===state.id))state.id=allowed[0].id;$('competition').innerHTML=allowed.map(c=>`<option value="${c.id}" ${c.id===state.id?'selected':''}>${c.name}</option>`).join('');}
function notify(text){$('status').textContent=text;}
function empty(title,text,url){return `<div class="empty"><div class="empty-symbol" aria-hidden="true">▦</div><h3>${e(title)}</h3><p>${e(text)}</p>${url?link(url,'Άνοιγμα επίσημης πηγής'):''}</div>`;}
function setRounds(){const rounds=[...new Set(state.matches.map(m=>m.round))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));state.round=chooseRound(state.matches,athensDay());$('round').innerHTML='<option value="">Όλες οι αγωνιστικές</option>'+rounds.map(r=>`<option value="${e(r)}">${e(r)}η αγωνιστική</option>`).join('');$('round').value=state.round;}
async function load(force=false){const request=++state.request,c=current(),season=state.season;state.matches=[];state.meta=null;$('view').innerHTML=empty('Φόρτωση δεδομένων','Ελέγχεται η επιλεγμένη πηγή.');$('refresh').disabled=true;let message='';
 try{
 if(isConnected(c.id)&&state.tab!=='tv'){
 const payload=await loadProvider(c.id,season,{force});if(request!==state.request)return;state.matches=payload.matches;state.meta=payload;message=payload.notice||'Προσωπικό στιγμιότυπο πηγής.';if(payload.fallback)message+=' Αποθηκευμένο αντίγραφο: '+payload.fallback;
 }else if(c.file&&state.tab!=='tv'){
  const url=`https://raw.githubusercontent.com/openfootball/football.json/master/${season}/${c.file}.json`,key=`sh-data-${c.id}-${season}`;let cached=read(key,null),payload;
  try{const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();const matches=normalizeFootball(data,c.id);payload={data,retrievedAt:new Date().toISOString(),source:url};if(request!==state.request)return;save(key,payload);state.matches=matches;message='Ανάκτηση από openfootball · CC0 · κοινοτική πηγή, χωρίς εγγύηση πληρότητας.';}
  catch(error){if(!cached){try{const r=await fetch(`./snapshots/${season}-${c.file}.json`);if(r.ok)cached=await r.json();}catch{}}if(!cached)throw error;state.matches=normalizeFootball(cached.data,c.id);payload=cached;message=`Δεν έγινε νέα ανάκτηση (${error.name==='TimeoutError'?'λήξη χρόνου':error.message}). Εμφανίζεται αποθηκευμένο αντίγραφο.`;}
  if(request!==state.request)return;state.meta=payload;
 }else if(season==='2026-27'){
  if(state.tab==='tv'){state.tvSources=[];let personal;try{personal=await loadProvider('elite',season);}catch{personal={matches:[]};}if(personal.source)state.tvSources.push(personal);if(request!==state.request)return;let tv=[];const streams=personal.matches.filter(m=>m.channel&&m.streamURL).map(m=>({...m,id:'stream-'+m.id,competition:'elite'}));let gblTV=[];try{const gbl=await loadProvider('gbl',season);state.tvSources.push(gbl);gblTV=gbl.matches.filter(m=>m.date&&m.time&&m.channel).map(m=>({...m,id:'tv-'+m.id,competition:'gbl'}));}catch{}if(request!==state.request)return;state.matches=[...tv,...streams,...gblTV].filter(m=>c.id==='all-tv'||m.competition===c.id);}
  else if(c.id==='elite')state.matches=eliteMatches;
  state.meta={retrievedAt:checkedAt,source:state.tab==='tv'?(c.id==='elite'?eliteTV:c.url):c.id==='elite'?eliteSchedule:c.ranking||c.url};
  if(state.tab==='tv'){state.meta=null;message='Ημερήσιες μεταδόσεις από ρητά δηλωμένα κανάλια ΕΣΑΚΕ και συνδέσμους ΕΟΚ. Χρόνοι ελέγχου στο κάτω μέρος της λίστας.';}else message='Δεν υπάρχει αυτόματη κάλυψη για αυτή την επιλογή.';
 }else{message='Δεν υπάρχει αποθηκευμένη κάλυψη για την επιλεγμένη σεζόν.';}
 }catch(error){if(request!==state.request)return;message=`Η πηγή δεν είναι διαθέσιμη (${error.message}). Δεν εμφανίζονται επινοημένα δεδομένα.`;}
 finally{if(request===state.request){setRounds();render();notify((navigator.onLine?'':'Εκτός σύνδεσης · ')+message);$('refresh').disabled=false;}}
}
function render(){const c=current();renderNav();$('page-title').textContent=state.tab==='standings'?'Βαθμολογίες διοργανώσεων':state.tab==='tv'?'Η αθλητική τηλεόραση':'Το πρόγραμμα των αγώνων';$('section-title').textContent=c.name;$('sport-label').textContent=c.sport==='all'?'ΑΘΛΗΤΙΚΗ ΤΗΛΕΟΡΑΣΗ':c.sport==='football'?'ΠΟΔΟΣΦΑΙΡΟ':'ΜΠΑΣΚΕΤ';$('round-label').hidden=['standings','tv'].includes(state.tab);$('tv-day').hidden=state.tab!=='tv';$('tv-date').value=state.tvDate;$('coverage').textContent=state.meta?.partial?'Μερική κάλυψη · TheSportsDB':c.id==='sl'?'Κοινοτική πηγή · CC0':'Στιγμιότυπο / επίσημοι σύνδεσμοι';
 const meta=state.meta;$('source-note').innerHTML=meta?`Σεζόν ${e(state.season)} · Ανάκτηση / έλεγχος: ${e(timestamp(meta.retrievedAt))} (Ελλάδα).<br>${link(meta.source,'Πρωτογενής πηγή')}<br>${c.file||c.id==='sl'?'Τα ωράρια της κοινοτικής πηγής παραλείπονται επειδή δεν δηλώνουν αξιόπιστα ζώνη ώρας. Δεν εμφανίζονται live scores.':'Το στιγμιότυπο μπορεί να έχει αλλάξει. Επιβεβαίωσε στην επίσημη πηγή πριν τον αγώνα.'}`:'Δεν έχει ανακτηθεί σύνολο δεδομένων για αυτή την επιλογή.';
 if(state.tab==='tv')$('source-note').innerHTML=(state.tvSources||[]).map(p=>`Έλεγχος: ${e(timestamp(p.retrievedAt))} · ${link(p.source,'Πηγή μεταδόσεων')}${p.fallback?' · Αποθηκευμένο αντίγραφο':''}<br>${e(p.copyright||'')}`).join('<br>')||'Δεν ανακτήθηκε πηγή μεταδόσεων.';
 if(meta?.copyright)$('source-note').innerHTML+=`<br>${e(meta.copyright)} ${link(meta.terms,'Όροι προσωπικής χρήσης')}`;
 if(state.tab==='standings'){renderTable(c);return;}
 let matches=filterMatches(state.matches,{round:state.tab==='tv'?'':state.round,search:state.search,favoritesOnly:state.only,favorites:state.favorites,date:state.tab==='tv'&&!state.archive?state.tvDate:''});
 matches.sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'').localeCompare(b.time||''));
 if(!matches.length){const hasData=state.matches.length>0;if(state.tab==='tv'){const selected=state.archive?'στο διαθέσιμο αρχείο':dateLabel(state.tvDate);$('view').innerHTML=empty('Δεν υπάρχουν καταχωρισμένες μεταδόσεις',`Για ${selected} δεν βρέθηκαν μεταδόσεις με τα επιλεγμένα φίλτρα. Αυτό δεν σημαίνει ότι δεν γίνονται αγώνες ή μεταδόσεις. Η κάλυψη είναι περιορισμένη. Δες το πλήρες ημερήσιο πρόγραμμα στα επίσημα κανάλια.`)+`<div class="source-note">${link('https://www.ert.gr/tv-program/','ΕΡΤ')} · ${link('https://www.cosmotetv.gr/program','COSMOTE TV')} · ${link('https://www.novasports.gr/tv-program/','Novasports')}<br>Διάλεξε την ίδια ημερομηνία και στην ιστοσελίδα του καναλιού.</div>`;return;}$('view').innerHTML=empty(hasData?'Δεν βρέθηκαν αγώνες':'Δεν υπάρχουν διαθέσιμα στοιχεία',hasData?'Άλλαξε αγωνιστική, αναζήτηση ή το φίλτρο αγαπημένων.':state.tab==='tv'?'Δεν υπάρχει επιβεβαιωμένη λίστα μεταδόσεων για αυτή τη διοργάνωση και σεζόν. Δες τα επίσημα προγράμματα καναλιών δεξιά.':c.note||'Η επιλεγμένη πηγή δεν επέστρεψε πρόγραμμα.',c.url);return;}
 let day='';let html=state.meta?.partial?`<div class="notice">${e(state.meta.notice)} ${link('https://www.thesportsdb.com/','Πηγή: TheSportsDB')}</div>`:state.tab==='tv'?'<div class="notice">Ημερήσιες μεταδόσεις από χρονολογημένες ανακοινώσεις. Περιορισμένη κάλυψη, όχι πλήρης οδηγός καναλιών. Για παλιές ημερομηνίες εμφανίζεται αρχείο.</div>':c.id==='elite'?'<div class="notice">Προσωπικό στιγμιότυπο επίσημου προγράμματος · 30 αγωνιστικές. Οι ώρες χωρίς ορισμό εμφανίζονται ως άγνωστες. Δεν συμπεραίνουμε κανάλι μετάδοσης από τη διοργάνωση.</div>':'';
 for(const m of matches){if(day!==m.date){day=m.date;html+=`<div class="match-date">${e(day?dateLabel(day):'Ημερομηνία δεν έχει οριστεί')}${day&&day<athensDay()?' · Αρχείο':''}</div>`;}const saved=state.favorites.includes(m.id);html+=`<article class="match"><div class="match-time">${e(m.time||'—')}<small>${m.time?'Ελλάδα':'Ώρα άγνωστη'}</small></div><div><div class="teams"><div class="team"><span class="team-mark" aria-hidden="true">${e(m.home.slice(0,2))}</span>${e(m.home)}</div><div class="team"><span class="team-mark" aria-hidden="true">${e(m.away.slice(0,2))}</span>${e(m.away)}</div></div>${m.channel?`<span class="tv-tag">▣ ${e(m.channel)} · ${link(m.source,'Πηγή')}${m.streamURL?' · '+link(m.streamURL,'Παρακολούθηση'):''}</span>`:''}</div><button class="star ${saved?'saved':''}" data-favorite="${e(m.id)}" aria-pressed="${saved}" aria-label="${saved?'Αφαίρεση από':'Προσθήκη στα'} αγαπημένα: ${e(m.home)} – ${e(m.away)}">${saved?'★':'☆'}</button></article>`;}
 $('view').innerHTML=html;
}
function renderTable(c){
 const meta=state.meta,football=c.sport==='football';let rows=meta?.standings||[],computed=false;
 if(!rows.length&&(c.file||c.id==='sl')&&state.matches.length){rows=calculateTable(state.matches,athensDay());computed=true;}
 if(!rows.length){$('view').innerHTML=empty('Δεν υπάρχει διαθέσιμη βαθμολογία',c.note||'Δεν έχει συνδεθεί πηγή για αυτή τη σεζόν.',c.ranking||c.url);return;}
 if(meta?.standingsSource)$('source-note').innerHTML+=`<br>${link(meta.standingsSource,'Πηγή κατάταξης')}`;
 const q=state.search.toLocaleLowerCase('el');rows=rows.filter(r=>r.team.toLocaleLowerCase('el').includes(q));
 const percent=['el','eurocup'].includes(c.id);
 const notice=computed?'Ενδεικτικός υπολογισμός από τελικά αποτελέσματα προηγούμενων ημερών. Δεν περιλαμβάνει ποινές ή ειδικές ισοβαθμίες. Εξαιρείται η σημερινή ημέρα.':'Δημοσιευμένη κατάταξη πηγής με χρόνο ελέγχου. Διατηρείται η σειρά, οι ισοβαθμίες και οι όμιλοι που επέστρεψε η πηγή.';
 $('view').innerHTML=`<div class="notice">${e(notice)}</div><div class="table-scroll"><table><caption class="fine">${computed?'Ενδεικτική':'Δημοσιευμένη'} κατάταξη · ${e(c.name)} · ${e(state.season)}</caption><thead><tr><th scope="col">#</th><th scope="col">Ομάδα</th><th scope="col">Αγ.</th><th scope="col">Ν</th>${football?'<th scope="col">Ι</th>':''}<th scope="col">Η</th><th scope="col">${percent?'% Ν':'Βαθ.'}</th></tr></thead><tbody>${rows.map((r,i)=>`${r.group&&r.group!==rows[i-1]?.group?`<tr><th colspan="${football?7:6}" scope="rowgroup">${e(r.group)}</th></tr>`:''}<tr><td>${r.rank}</td><td>${e(r.team)}</td><td>${r.played}</td><td>${r.wins}</td>${football?`<td>${r.draws}</td>`:''}<td>${r.losses}</td><td>${percent?e(r.winRate||'—'):r.points}</td></tr>`).join('')}</tbody></table></div>`;
}
function showHelp(){const cards=competitions.map(c=>`<div><b>${e(c.name)}</b><p>${e(c.file?'Δωρεάν openfootball / CC0. Δοκιμάστηκε HTTP 200 και CORS *. Αυτόματη ανάκτηση όταν ανοίγεις τη διοργάνωση, με αποθηκευμένο αντίγραφο αν αποτύχει. Κοινοτικά στοιχεία, όχι επίσημη πιστοποίηση.':c.note)}</p>${link(c.url,'Επίσημη ιστοσελίδα')}</div>`).join('');$('help-content').innerHTML=`<h3>Εγκατάσταση σε Android</h3><p>Άνοιξε τον HTTPS σύνδεσμο με Chrome και δεν απαιτείται σύνδεση. Πάτησε «Εγκατάσταση εφαρμογής» ή μενού ⋮ → «Προσθήκη στην αρχική οθόνη» → «Εγκατάσταση». Η επιλογή εξαρτάται από τον browser. Δεν απαιτείται app store.</p><h3>Εγκατάσταση σε PC</h3><p>Σε Chrome ή Edge, άνοιξε τον ίδιο σύνδεσμο και πάτησε το εικονίδιο εγκατάστασης στη γραμμή διευθύνσεων ή την επιλογή εγκατάστασης από το μενού. Τοπικά εκκινείται και από localhost μέσω του παρεχόμενου οδηγού.</p><h3>Offline & ιδιωτικότητα</h3><p>Μετά την πρώτη επιτυχή φόρτωση, το κέλυφος και τα αποθηκευμένα δεδομένα παραμένουν στη συσκευή. Τα αγαπημένα αποθηκεύονται τοπικά χωρίς συγχρονισμό. Οι εξωτερικές πηγές και η αρχική σύνδεση χρειάζονται internet. Οι πηγές ελέγχονται όταν ανοίγεις ή ανανεώνεις τη διοργάνωση. Χωρίς διαφημίσεις ή analytics στην εφαρμογή.</p><h3>Τι έχει ελεγχθεί</h3><p>Έλεγχος πηγών: 20/10/2026. Δεν χρησιμοποιούνται placeholders αγώνων, βαθμολογιών ή μεταδόσεων. Τα αρχικά γραμμάτων δίπλα στις ομάδες είναι διακοσμητικά, όχι επίσημα εμβλήματα. Το αρχικό screenshot δεν ήταν προσβάσιμο στη μεταφερμένη συνομιλία· η διάταξη ακολουθεί τη γραπτή περιγραφή.</p><div class="help-grid">${cards}</div><h3>Τηλεόραση</h3><p>Η ημερήσια λίστα ανανεώνεται από τις ρητές αναφορές μετάδοσης ΕΟΚ και ΕΣΑΚΕ. Οι υπόλοιπες μεταδόσεις ελέγχονται στα επίσημα προγράμματα καναλιών. Δεν υπάρχει πλήρης δωρεάν ελληνικός EPG συνδεδεμένος. Δεν συμπεραίνουμε κανάλι από τα δικαιώματα μιας διοργάνωσης. Οι δοκιμές λανθασμένων URL COSMOTE / Nova επέστρεψαν 404 και αντικαταστάθηκαν με τους επίσημους συνδέσμους των προγραμμάτων.</p><p>${link('https://github.com/openfootball/football.json/blob/master/LICENSE.md','Άδεια openfootball CC0')} · ${link('https://www.football-data.org/coverage','Κάλυψη football-data.org')}</p>`;$('help-dialog').showModal();}
for(const id of ['side-nav','top-nav','bottom-nav'])$(id).addEventListener('click',event=>{const b=event.target.closest('[data-tab]');if(!b)return;state.tab=b.dataset.tab;if(state.tab==='tv')state.id='all-tv';choices();load();});
$('competition').addEventListener('change',()=>{state.id=$('competition').value;load();});$('season').addEventListener('change',()=>{state.season=$('season').value;load();});$('round').addEventListener('change',()=>{state.round=$('round').value;render();});$('search').addEventListener('input',()=>{state.search=$('search').value;render();});$('favorites').addEventListener('change',()=>{state.only=$('favorites').checked;render();});
$('view').addEventListener('click',event=>{const b=event.target.closest('[data-favorite]');if(!b)return;const id=b.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];if(!save('sh-favorites',state.favorites))notify('Τα αγαπημένα λειτουργούν προσωρινά· η αποθήκευση του browser δεν είναι διαθέσιμη.');render();});
$('refresh').addEventListener('click',()=>load(true));$('help').onclick=showHelp;$('data-help').onclick=showHelp;$('close-help').onclick=()=>$('help-dialog').close();
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else showHelp();};window.addEventListener('appinstalled',()=>{$('install').textContent='Εγκατεστημένο';});
window.addEventListener('offline',()=>notify('Εκτός σύνδεσης · τα δεδομένα είναι αποθηκευμένα στιγμιότυπα. Οι εξωτερικές πηγές χρειάζονται internet.'));window.addEventListener('online',()=>load());
$('today').textContent=new Intl.DateTimeFormat('el-GR',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Athens'}).format(new Date());
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>notify('Δεν ενεργοποιήθηκε η offline λειτουργία. Άνοιξε την εφαρμογή μέσω HTTPS ή localhost.'));
$('tv-date').onchange=()=>{if($('tv-date').value){state.tvDate=$('tv-date').value;state.archive=false;$('tv-archive').checked=false;render();}};
$('prev-day').onclick=()=>{state.tvDate=shiftDay(state.tvDate,-1);state.archive=false;$('tv-archive').checked=false;render();};
$('next-day').onclick=()=>{state.tvDate=shiftDay(state.tvDate,1);state.archive=false;$('tv-archive').checked=false;render();};
$('today-button').onclick=()=>{state.tvDate=athensDay();state.archive=false;$('tv-archive').checked=false;render();};
$('tv-archive').onchange=()=>{state.archive=$('tv-archive').checked;render();};
choices();renderNav();load();
